<script setup lang="ts">
import {ref,reactive,computed,onMounted} from 'vue';import {get,post,patch} from '../api/client';import type {Model,Hygiene,Building,FileAsset} from '../api/types';import {errorText,notify,localDate,dateTime,isoTime,statusNames} from '../ui';import Drawer from '../components/Drawer.vue';import Pagination from '../components/Pagination.vue';import LookupSelect from '../components/LookupSelect.vue';import UploadField from '../components/UploadField.vue';import StatusBadge from '../components/StatusBadge.vue';import Icon from '../components/Icon.vue';
const items=ref<Hygiene[]>([]),buildings=ref<Building[]>([]),busy=ref(false),error=ref(''),page=ref(1),total=ref(0),filters=reactive({q:'',buildingId:'',grade:'',startDate:'',endDate:''});
const selected=ref<Hygiene>(),modal=ref<'form'|'detail'|null>(null),mode=ref<'create'|'correction'|'recheck'>('create'),saving=ref(false),dirty=ref(false),formError=ref(''),images=ref<FileAsset[]>([]),uploadBlocked=ref(false),inspectedLocal=ref(''),history=ref<Model<'CorrectionEvent'>[]>([]);
const form=reactive<Model<'HygieneRequest'>>({roomId:'',inspectionDate:localDate(),round:'ROUTINE',floorScore:25,deskScore:25,bedScore:25,bathroomScore:25,issueNote:'',remediationNote:'',imageIds:[]});const correctionReason=ref('');
const scores=[['floorScore','地面'],['deskScore','桌面'],['bedScore','床铺'],['bathroomScore','卫生间']] as const;
const score= computed(()=>scores.reduce((sum,[key])=>sum+Number(form[key]||0),0));const grade=computed(()=>score.value>=90?'优秀':score.value>=80?'良好':score.value>=60?'合格':'待整改');
async function load(){busy.value=true;error.value='';try{const r=await get<Model<'HygienePage'>>('/hygiene-inspections',{...filters,page:page.value,pageSize:20});items.value=r.items;total.value=r.total;}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
function edit(h?:Hygiene,next:'create'|'correction'|'recheck'='create'){selected.value=h;mode.value=next;Object.assign(form,{roomId:h?.roomId||'',inspectionDate:next==='correction'?h?.inspectionDate:localDate(),round:next==='recheck'?'RECHECK':next==='correction'?h?.round:'ROUTINE',floorScore:next==='correction'?h?.floorScore:25,deskScore:next==='correction'?h?.deskScore:25,bedScore:next==='correction'?h?.bedScore:25,bathroomScore:next==='correction'?h?.bathroomScore:25,issueNote:next==='correction'?h?.issueNote:'',remediationNote:next==='correction'?h?.remediationNote:'',relatedInspectionId:next==='recheck'?h?.id:h?.relatedInspectionId,imageIds:[],expectedVersion:next==='correction'?h?.version:undefined});images.value=next==='correction'?[...(h?.images||[])]:[];inspectedLocal.value='';correctionReason.value='';formError.value='';dirty.value=false;uploadBlocked.value=false;modal.value='form';}
async function detail(h:Hygiene){selected.value=h;history.value=[];modal.value='detail';formError.value='';try{const [r,events]=await Promise.all([get<Hygiene>(`/hygiene-inspections/${h.id}`),get<Model<'CorrectionEvent'>[]>(`/hygiene-inspections/${h.id}/history`)]);selected.value=r;history.value=events;}catch(e){formError.value=errorText(e);}}
async function save(){saving.value=true;formError.value='';try{const body:Model<'HygieneRequest'>={...form,imageIds:images.value.map(i=>i.id),inspectedAt:isoTime(inspectedLocal.value)||(mode.value==='correction'?selected.value?.inspectedAt:undefined)};if(mode.value==='correction'&&selected.value)await patch(`/hygiene-inspections/${selected.value.id}`,{...body,correctionReason:correctionReason.value.trim()});else await post('/hygiene-inspections',body);dirty.value=false;modal.value=null;notify(mode.value==='correction'?'评分已修正，原成绩与原因已留痕':'卫生评分已保存');await load();}catch(e){formError.value=errorText(e);}finally{saving.value=false;}}
async function voidRecord(){if(!selected.value)return;const reason=window.prompt('请填写作废原因（保留原记录与审计）');if(!reason?.trim())return;saving.value=true;try{await post(`/hygiene-inspections/${selected.value.id}/void`,{expectedVersion:selected.value.version,reason:reason.trim()});modal.value=null;notify('巡检已作废并保留记录');await load();}catch(e){formError.value=errorText(e);}finally{saving.value=false;}}
function search(){page.value=1;void load();}function turn(p:number){page.value=p;void load();}
onMounted(async()=>{try{buildings.value=(await get<Model<'BuildingPage'>>('/buildings',{pageSize:100})).items;}catch(e){error.value=errorText(e);}await load();});
</script>
<template><div class="page-heading"><div><h1>卫生巡检</h1><p>四项评分、整改建议与复查，让宿舍环境的变化有迹可循。</p></div><button class="btn primary" @click="edit()"><Icon name="plus"/>录入卫生评分</button></div><p v-if="error" class="error-banner" role="alert">{{error}}</p><section class="panel"><form class="filters" @submit.prevent="search"><label>房号 / 关键词<input v-model="filters.q" placeholder="房号或检查说明"></label><label>楼栋<select v-model="filters.buildingId"><option value="">全部负责楼栋</option><option v-for="b in buildings" :key="b.id" :value="b.id">{{b.name}}</option></select></label><label>评分等级<select v-model="filters.grade"><option value="">全部</option><option v-for="g in ['EXCELLENT','GOOD','PASS','RECTIFY']" :key="g" :value="g">{{statusNames[g]}}</option></select></label><label>开始日期<input v-model="filters.startDate" type="date"></label><label>结束日期<input v-model="filters.endDate" type="date" :min="filters.startDate"></label><button class="btn primary" :disabled="busy">查询</button><button class="btn" type="button" @click="Object.assign(filters,{q:'',buildingId:'',grade:'',startDate:'',endDate:''});search()">重置</button></form><p v-if="busy" class="panel-body loading">正在读取卫生记录…</p><div class="table-wrap"><table><thead><tr><th>宿舍</th><th>日期 / 轮次</th><th>得分</th><th>等级</th><th>检查人</th><th>问题记录</th><th>操作</th></tr></thead><tbody><tr v-for="h in items" :key="h.id"><td>{{h.buildingName}} {{h.roomNo}}</td><td>{{h.inspectionDate}}<small>{{statusNames[h.round]||h.round}}</small></td><td class="num">{{h.totalScore}} / 100</td><td><StatusBadge :status="h.grade"/></td><td>{{h.inspectorName}}</td><td>{{h.issueNote||'—'}}</td><td><button class="text-link" @click="detail(h)">查看与更正</button></td></tr><tr v-if="!busy&&!items.length"><td colspan="7" class="empty-state">暂无匹配的卫生记录，可调整筛选或录入评分。</td></tr></tbody></table></div><Pagination :page="page" :page-size="20" :total="total" :busy="busy" @change="turn"/></section><Drawer v-if="modal==='form'" :title="mode==='correction'?'更正卫生评分':mode==='recheck'?'录入整改复查':'录入卫生评分'" :busy="saving" :dirty="dirty" @close="modal=null"><form class="form" @input="dirty=true" @submit.prevent="save"><div class="score-total"><span>本次总分 / {{grade}}</span><strong>{{score}}</strong></div><LookupSelect v-model="form.roomId" kind="room" label="检查房间 *" :initial-label="selected?selected.buildingName+' '+selected.roomNo:undefined"/><div class="form-row"><label>检查日期 *<input v-model="form.inspectionDate" type="date" required :max="localDate()"></label><label>巡检轮次<select v-model="form.round"><option value="ROUTINE">日常巡检</option><option value="RECHECK">整改复查</option><option value="RECHECK2">第二次复查</option><option value="RECHECK3">第三次复查</option></select></label></div><label>实际检查时刻<input v-model="inspectedLocal" type="datetime-local" :required="mode!=='correction'&&form.inspectionDate<localDate()"><small>补录时请填写实际检查时刻；留空使用当前时间，更正则保留原检查时间。</small></label><div><div v-for="[key,label] in scores" :key="key" class="score-row"><label :for="key">{{label}}<small>满分25分</small></label><input :id="key" v-model.number="form[key]" type="number" min="0" max="25" step="1" required></div></div><label>问题与扣分说明 {{score<60?'*':''}}<textarea v-model.trim="form.issueNote" :required="score<60" maxlength="1000"/></label><label>整改建议<textarea v-model.trim="form.remediationNote" maxlength="1000"/></label><label v-if="mode==='correction'">更正原因 *<textarea v-model.trim="correctionReason" required minlength="2" maxlength="500"/></label><UploadField v-model="images" usage="INSPECTION" :disabled="saving" @blocked="uploadBlocked=$event"/><p v-if="formError" class="error-banner" role="alert">{{formError}}</p><button class="btn primary" :disabled="saving||uploadBlocked">{{saving?'正在保存…':mode==='correction'?'保存更正并留痕':'保存卫生评分'}}</button></form></Drawer><Drawer v-if="modal==='detail'&&selected" :title="selected.buildingName+' '+selected.roomNo+' 卫生记录'" :subtitle="selected.inspectionDate+' · '+(statusNames[selected.round]||selected.round)" :busy="saving" @close="modal=null"><p v-if="formError" class="error-banner">{{formError}}</p><div class="score-total"><StatusBadge :status="selected.grade"/><strong>{{selected.totalScore}}</strong></div><div v-for="[key,label] in scores" :key="key" class="score-row"><span>{{label}}</span><span class="num">{{selected[key]}} / 25</span></div><section class="detail-section" style="margin-top:24px"><h3>问题与整改建议</h3><p class="description">{{selected.issueNote||'无问题记录'}}<br>{{selected.remediationNote||'无补充整改建议'}}</p></section><section v-if="selected.images.length" class="detail-section"><h3>现场图片</h3><div class="image-grid"><a v-for="file in selected.images" :key="file.id" :href="file.url" target="_blank"><img :src="file.thumbnailUrl" :alt="file.originalName"></a></div></section><section class="detail-section"><h3>修正与操作历史</h3><ol class="timeline"><li v-for="h in history" :key="h.id"><strong>{{h.action==='CORRECT'?'更正评分':h.action==='VOID'?'作废记录':h.action}}</strong><p>{{h.note}}</p><small>{{dateTime(h.createdAt)}} · {{h.operatorName}}</small><details v-if="h.changes"><summary>查看变更明细</summary><pre class="changes-json">{{h.changes}}</pre></details></li></ol><p v-if="!history.length" class="muted">当前记录尚无更正。</p></section><template #footer><button class="btn primary" @click="edit(selected,'correction')">更正评分</button><button class="btn" @click="edit(selected,'recheck')">录入复查</button><button class="btn danger" :disabled="saving" @click="voidRecord">作废记录</button></template></Drawer></template>
